oxy_webhelp_navlinks = {"administer_agent_cloud-d39536e63820":{"topics":[{"title":"Access control for <span class=\"ph\">Agent Cloud<\/span>","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">Agent Cloud<\/span> separates seeing what it found from reading what agents said.         Session content is the most sensitive data that <span class=\"ph\">Agent Cloud<\/span> holds, so viewing it         requires its own privilege, which no built-in role includes.<\/p>","href":"agent_cloud\/rac_rbac_overview_all.html","attributes":{"data-id":"rac_rbac_overview"},"menu":{"hasChildren":false},"tocID":"rac_rbac_overview-d39536e63834","next":"rac_rbac_overview-d39536e63834"},{"title":"Event log and audit log","shortdesc":"<p class=\"shortdesc\">The event log records platform activity in <span class=\"ph\">Agent Cloud<\/span>, such as policy         updates and connection changes. The audit log records who did what. Open both from the         Events menu.<\/p>","href":"agent_cloud\/events_page_agent_cloud.html","attributes":{"data-id":"events_page_agent_cloud"},"menu":{"hasChildren":false},"tocID":"events_page_agent_cloud-d39536e63880","topics":[]},{"title":"Best practices for AI agents managed by <span class=\"ph\">Agent Cloud<\/span>","shortdesc":"<p class=\"shortdesc\">Follow these practices to roll out <span class=\"ph\">Agent Cloud<\/span> safely and to get the most         accurate inventory, monitoring, and enforcement for your agents.<\/p>","href":"agent_cloud\/agent_cloud_best_practices.html","attributes":{"data-id":"agent_cloud_best_practices"},"menu":{"hasChildren":false},"tocID":"agent_cloud_best_practices-d39536e63894","topics":[]}]}};